const errorHandler = (storeApi) => (next) => (action) => {
  if (action.type.endsWith('/rejected')) {
    const error = action.payload || action.error.message;
    console.error('Action failed:', action.type, error);
    // Optionally dispatch a global error action
    storeApi.dispatch(showErrorToast(error));
  }
  return next(action);
};

const store = configureStore({
  reducer: rootReducer,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware().concat(errorHandler)
});
